-- PawWing SOS v5.3 cloud database schema (Supabase/Postgres)
-- Run this file once in Supabase -> SQL Editor.

create extension if not exists pgcrypto;

create table if not exists public.contacts (
  id text primary key,
  country text not null,
  domain text not null check (domain in ('animal','bird','both')),
  type text not null check (type in ('Vet','Rescuer','Shelter','Shop')),
  name text not null,
  state text,
  city text,
  phones jsonb not null default '[]'::jsonb,
  address text not null,
  email text,
  website text,
  open24 boolean not null default false,
  services jsonb not null default '[]'::jsonb,
  source text,
  national boolean not null default false,
  verified boolean not null default false,
  community boolean not null default false,
  checked date,
  status text not null default 'approved' check (status in ('approved','deleted')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.contact_submissions (
  id uuid primary key default gen_random_uuid(),
  country text not null,
  domain text not null check (domain in ('animal','bird','both')),
  type text not null check (type in ('Vet','Rescuer','Shelter','Shop')),
  name text not null,
  state text,
  city text,
  phones jsonb not null default '[]'::jsonb,
  address text not null,
  email text,
  website text,
  open24 boolean not null default false,
  services jsonb not null default '[]'::jsonb,
  source text,
  national boolean not null default false,
  submitter_note text,
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  reviewed_by text,
  reviewed_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists public.audit_log (
  id bigint generated by default as identity primary key,
  admin_username text not null,
  action text not null,
  entity_type text not null,
  entity_id text,
  before_data jsonb,
  after_data jsonb,
  created_at timestamptz not null default now()
);

create index if not exists contacts_lookup_idx on public.contacts(country, state, city, domain, type, status);
create index if not exists contacts_name_idx on public.contacts(lower(name));
create index if not exists submissions_status_idx on public.contact_submissions(status, created_at desc);
create index if not exists audit_entity_idx on public.audit_log(entity_type, entity_id, created_at desc);

-- The browser never writes directly to these tables. Vercel server functions use
-- the server-only service-role key. RLS is enabled as an extra database boundary.
alter table public.contacts enable row level security;
alter table public.contact_submissions enable row level security;
alter table public.audit_log enable row level security;

revoke all on table public.contacts from anon, authenticated;
revoke all on table public.contact_submissions from anon, authenticated;
revoke all on table public.audit_log from anon, authenticated;

-- Seed the built-in v5.2 directory. ON CONFLICT DO NOTHING protects later admin edits.
on conflict (id) do nothing;

